import type { Plugin } from "../../kernel/types";

const VERSION = "1.0.0";

// 纯计算：安全的四则运算求值器（仅数字与 + - * / ( ) ，无任何 IO/进程/网络）
function evaluate(expr: string): number {
  const s = expr.replace(/\s+/g, "");
  if (s.length === 0) throw new Error("空表达式");
  if (!/^[0-9+\-*/().]+$/.test(s)) throw new Error("表达式包含非法字符");

  let pos = 0;

  function parseExpression(): number {
    let value = parseTerm();
    while (pos < s.length && (s[pos] === "+" || s[pos] === "-")) {
      const op = s[pos++];
      const rhs = parseTerm();
      value = op === "+" ? value + rhs : value - rhs;
    }
    return value;
  }

  function parseTerm(): number {
    let value = parseFactor();
    while (pos < s.length && (s[pos] === "*" || s[pos] === "/")) {
      const op = s[pos++];
      const rhs = parseFactor();
      value = op === "*" ? value * rhs : value / rhs;
    }
    return value;
  }

  function parseFactor(): number {
    if (s[pos] === "(") {
      pos++;
      const value = parseExpression();
      if (s[pos] !== ")") throw new Error("括号不匹配");
      pos++;
      return value;
    }
    if (s[pos] === "-") {
      pos++;
      return -parseFactor();
    }
    const start = pos;
    while (pos < s.length && (s[pos] >= "0" && s[pos] <= "9" || s[pos] === ".")) pos++;
    if (start === pos) throw new Error("无法解析的表达式");
    const num = parseFloat(s.slice(start, pos));
    if (Number.isNaN(num)) throw new Error("无效数字");
    return num;
  }

  const result = parseExpression();
  if (pos !== s.length) throw new Error("表达式存在多余内容");
  if (!Number.isFinite(result)) throw new Error("结果非有限数");
  return result;
}

const mathCheckRole = {
  name: "math-check",
  version: VERSION,
  description: "读取用户给出的算式并只报告计算结果（只读、纯计算，无副作用）。",
  permissions: { scope: "readonly" },
  sideEffect: "readonly",
  parameters: {
    type: "object",
    properties: {
      expression: { type: "string", description: "要计算的算术表达式，例如 3*4" }
    },
    required: ["expression"]
  },
  outputSchema: {
    type: "object",
    properties: {
      expression: { type: "string" },
      result: { type: "number" }
    },
    required: ["expression", "result"]
  },
  async handler(args: any, _tctx: any) {
    const raw = args && args.expression != null ? String(args.expression) : "";
    const expression = raw.trim();
    if (!expression) {
      return { ok: false, error: { code: "INVALID_INPUT", message: "缺少 expression" } };
    }
    try {
      const result = evaluate(expression);
      return { ok: true, data: { expression, result } };
    } catch (e) {
      return { ok: false, error: { code: "EVAL_ERROR", message: (e as Error).message } };
    }
  }
};

export default {
  id: "math-role",
  name: "Math Role",
  version: VERSION,
  onLoad(ctx: any) {
    ctx.register({ kind: "role", role: mathCheckRole });
  }
} satisfies Plugin;

